{
  "S1_split_unit": {
    "code": "A",
    "quote": "In experiments, each sample is extracted from two vibration signals as shown in Figure 2. We use half of the vibration signal to generate training samples and the rest to generate test samples. The train samples are generated by the sliding window of size 2048 points sliding with 80 points shift step. The test samples are generated by the same size sliding window sliding without overlap.",
    "location": "p.4",
    "reason": "训练和测试样本来自同一原始振动信号的不同部分（一半和另一半），属于同一文件切出的窗口同时出现在训练和测试中，因此是窗口/样本级切分（A）。"
  },
  "S2_validation": {
    "code": "B",
    "quote": "Other methods use 60% samples as the training set and the rest samples as the validation set.",
    "location": "p.5",
    "reason": "正文明确说明除SVM外的方法使用60%样本作为训练集，其余作为验证集，验证集与测试集不重叠，因此是独立验证集。"
  },
  "S3_checkpoint_rule_code": {
    "code": "N",
    "quote": "",
    "location": "",
    "reason": "代码文件为NO_CODE，没有公开代码，无法查看checkpoint选择规则。"
  },
  "S4a_text_discloses": {
    "code": "N",
    "quote": "",
    "location": "",
    "reason": "正文未明确说明报告的是哪一轮或按什么挑选模型，只提到了训练过程，没有关于checkpoint选择规则的描述。"
  },
  "S4b_text_matches_code": {
    "code": "N",
    "quote": "",
    "location": "",
    "reason": "没有公开代码，无法核对正文与代码的一致性。"
  },
  "S5_runs": {
    "code": "20",
    "quote": "Together, for every series of experiments, we repeated twenty times in total.",
    "location": "p.5",
    "reason": "文中明确说每个系列实验重复了20次（5个不同训练集×4次重复）。"
  },
  "S5_spread_reported": {
    "code": "Y",
    "quote": "We also found that the accuracies of SVM, WDCNN and few-shot learning all increase while their standard deviations decline with increasing number of training samples.",
    "location": "p.5",
    "reason": "明确提到了标准差（standard deviations），因此报告了方差信息。"
  },
  "S6_metrics": {
    "code": "M",
    "quote": "Figure 5(c),(d) show confusion matrix results for 90 training samples.",
    "location": "p.5",
    "reason": "论文主要报告准确率，并展示了混淆矩阵（图5），但没有报告F1、精确率、召回率等指标，因此属于准确率加混淆矩阵。"
  },
  "S7_noise_protocol": {
    "code": "T",
    "quote": "the models are trained with the original data provided by CWRU, then tested with added different SNR white Gaussian test samples.",
    "location": "p.6",
    "reason": "训练使用原始干净数据，测试时添加不同信噪比的白高斯噪声，符合训练用干净数据、测试加噪的协议。"
  },
  "S8_traceability": {
    "code": "W",
    "quote": "All our models and datasets in this study are open sourced and can be downloaded from https://mekhub.cn/as/fault_diagnosis_with_few-shot_learning/.",
    "location": "p.1",
    "reason": "论文声称开源了模型和数据集，但代码文件为NO_CODE，没有代码。这里将“models”理解为训练好的模型权重，因此填W（权重）；没有明确提到代码、日志或结果文件。"
  }
}
